(md5('mq-card-1')::uuid, null, 1, $mq$What four prices does a candle show?$mq$, $mq$Open, high, low, close.$mq$),
(md5('mq-card-2')::uuid, null, 1, $mq$Bullish candle?$mq$, $mq$Closes above where it opened.$mq$),
(md5('mq-card-3')::uuid, null, 1, $mq$Bearish candle?$mq$, $mq$Closes below where it opened.$mq$),
(md5('mq-card-4')::uuid, null, 1, $mq$What does a long lower wick at support suggest?$mq$, $mq$Buyers rejected lower prices there.$mq$),
(md5('mq-card-5')::uuid, null, 1, $mq$Why wait for the candle to close?$mq$, $mq$Spikes inside a candle are noise. The close shows what actually held.$mq$),
(md5('mq-card-6')::uuid, null, 1, $mq$Job of the higher timeframe?$mq$, $mq$The map: trend direction and key levels.$mq$),
(md5('mq-card-7')::uuid, null, 1, $mq$Job of the entry timeframe?$mq$, $mq$The door: a clean entry at a level from the map.$mq$),
(md5('mq-card-8')::uuid, null, 1, $mq$What is the Confirmation Fog?$mq$, $mq$Only looking for evidence that agrees with you, e.g. switching timeframes until one does.$mq$),
(md5('mq-card-9')::uuid, null, 1, $mq$Name the three main forex sessions.$mq$, $mq$Asian, London, New York.$mq$),
(md5('mq-card-10')::uuid, null, 1, $mq$Why check the news calendar every day?$mq$, $mq$High-impact news can spike price, widen spreads and break firm rules.$mq$),
(md5('mq-card-11')::uuid, null, 2, $mq$Uptrend structure?$mq$, $mq$Higher highs and higher lows.$mq$),
(md5('mq-card-12')::uuid, null, 2, $mq$Downtrend structure?$mq$, $mq$Lower highs and lower lows.$mq$),
(md5('mq-card-13')::uuid, null, 2, $mq$What puts an uptrend in question?$mq$, $mq$A clear close below the most recent higher low.$mq$),
