(md5('mq-card-15')::uuid, null, 2, $mq$Resistance?$mq$, $mq$An area above price where selling stepped in before.$mq$),
(md5('mq-card-16')::uuid, null, 2, $mq$Role reversal?$mq$, $mq$Broken resistance acting as support (or broken support acting as resistance).$mq$),
(md5('mq-card-17')::uuid, null, 2, $mq$How many key levels per pair?$mq$, $mq$Two or three, from the higher timeframe.$mq$),
(md5('mq-card-18')::uuid, null, 2, $mq$Uptrend line connects…?$mq$, $mq$Swing lows.$mq$),
(md5('mq-card-19')::uuid, null, 2, $mq$When is a trendline more meaningful?$mq$, $mq$After a third touch that respects it.$mq$),
(md5('mq-card-20')::uuid, null, 2, $mq$Where to trade in a range?$mq$, $mq$Near the edges. Skip the middle.$mq$),
(md5('mq-card-21')::uuid, null, 2, $mq$Fakeout?$mq$, $mq$A break of a level that quickly reverses back inside.$mq$),
(md5('mq-card-22')::uuid, null, 2, $mq$Safer breakout entry?$mq$, $mq$Wait for a close beyond the level, enter on the retest.$mq$),
(md5('mq-card-23')::uuid, null, 4, $mq$Minimum reward:risk in your armor check?$mq$, $mq$1:2. Reward at least twice the risk.$mq$),
(md5('mq-card-24')::uuid, null, 4, $mq$Position size formula?$mq$, $mq$Risk $ ÷ (stop distance in pips × $ per pip per lot).$mq$),
(md5('mq-card-25')::uuid, null, 4, $mq$Why round lot size DOWN?$mq$, $mq$So you never risk more than planned.$mq$),
(md5('mq-card-26')::uuid, null, 4, $mq$What is 1R?$mq$, $mq$The dollar amount you risk on a trade. Results are measured in R.$mq$),
(md5('mq-card-27')::uuid, null, 5, $mq$What should you do after a loss?$mq$, $mq$Take the Campfire cooldown before looking for the next trade.$mq$),
(md5('mq-card-28')::uuid, null, 5, $mq$What earns XP in Market Quest?$mq$, $mq$Following your process. Never profit.$mq$),
(md5('mq-card-29')::uuid, null, 5, $mq$Two losses in a row today?$mq$, $mq$Loss-streak protocol: done for the day.$mq$),
(md5('mq-card-30')::uuid, null, 3, $mq$Where does your stop go?$mq$, $mq$Where your trade idea is clearly wrong, beyond the level.$mq$)
on conflict (id) do update set zone = excluded.zone, front = excluded.front, back = excluded.back;

insert into public.drills (id, zone, title, kind, payload) values
($mq$drill-trend-1$mq$, 2, $mq$Name the Trend I$mq$, $mq$trend$mq$, $mq${"seed":11,"shape":"up","questions":[{"q":"What is the trend on this chart?","options":["Uptrend","Downtrend","Range"],"answer":0,"why":"Higher highs and higher lows: an uptrend."},{"q":"Which trades fit this chart best?","options":["Longs at support","Shorts at resistance","Any direction"],"answer":0,"why":"Trade with the trend: longs at support."}]}$mq$::jsonb),
($mq$drill-trend-2$mq$, 2, $mq$Name the Trend II$mq$, $mq$trend$mq$, $mq${"seed":23,"shape":"down","questions":[{"q":"What is the trend on this chart?","options":["Uptrend","Downtrend","Range"],"answer":1,"why":"Lower highs and lower lows: a downtrend."},{"q":"A small bounce appears. Most likely it is:","options":["A new uptrend","A pullback in the downtrend","A guaranteed reversal"],"answer":1,"why":"Bounces inside a downtrend are usually pullbacks."}]}$mq$::jsonb),
($mq$drill-trend-3$mq$, 2, $mq$Name the Trend III$mq$, $mq$trend$mq$, $mq${"seed":37,"shape":"range","questions":[{"q":"What is price doing?","options":["Uptrend","Downtrend","Ranging"],"answer":2,"why":"Highs and lows stay roughly level: a range."},{"q":"Where is the worst place to enter?","options":["Near the floor","Near the ceiling","In the middle"],"answer":2,"why":"The middle of a range has poor RR and no edge."}]}$mq$::jsonb),
($mq$drill-levels-1$mq$, 2, $mq$Find the Floor$mq$, $mq$level$mq$, $mq${"seed":41,"shape":"range","lines":[{"label":"A","at":"high"},{"label":"B","at":"mid"},{"label":"C","at":"low"}],"questions":[{"q":"Which line is support?","options":["Line A","Line B","Line C"],"answer":2,"why":"Support is the floor where price bounced: line C."},{"q":"Which line is resistance?","options":["Line A","Line B","Line C"],"answer":0,"why":"Resistance is the ceiling: line A."},{"q":"Buying at line B gives you:","options":["Great RR","Poor RR in the middle of the range","A guaranteed win"],"answer":1,"why":"From the middle, the target and stop are both close."}]}$mq$::jsonb),
($mq$drill-levels-2$mq$, 2, $mq$Stop Placement$mq$, $mq$level$mq$, $mq${"seed":53,"shape":"range","lines":[{"label":"A","at":"high"},{"label":"C","at":"low"}],"questions":[{"q":"You buy near line C. Where does the stop go?","options":["Just above line A","Just below line C","At your entry"],"answer":1,"why":"Below the support zone, where the idea is wrong."},{"q":"Where is a logical target?","options":["Near line A","Below line C","No target"],"answer":0,"why":"The other side of the range."}]}$mq$::jsonb),
($mq$drill-rr-1$mq$, 4, $mq$RR Calculator I$mq$, $mq$rr$mq$, $mq${"seed":61,"shape":"up","questions":[{"q":"Long EURUSD: entry 1.1000, stop 1.0980, target 1.1040. What is the RR?","options":["1:1","1:2","1:3"],"answer":1,"why":"Risk 20 pips, reward 40 pips = 1:2."},{"q":"Does it pass the armor check minimum?","options":["Yes","No"],"answer":0,"why":"1:2 meets the minimum."},{"q":"Same trade with target 1.1030?","options":["1:1.5, fails","1:2, passes","1:3, passes"],"answer":0,"why":"30 ÷ 20 = 1.5. Look for 1:2 or better."}]}$mq$::jsonb),
($mq$drill-rr-2$mq$, 4, $mq$RR Calculator II$mq$, $mq$rr$mq$, $mq${"seed":67,"shape":"down","questions":[{"q":"Short gold: entry 2400, stop 2405, target 2385. RR?","options":["1:2","1:3","1:4"],"answer":1,"why":"Risk $5, reward $15 = 1:3."},{"q":"Short EURUSD: entry 1.0900, stop 1.0925, target 1.0850. RR?","options":["1:2","1:2.5","1:1"],"answer":0,"why":"Risk 25 pips, reward 50 pips = 1:2."}]}$mq$::jsonb),
($mq$drill-size-1$mq$, 4, $mq$Position Size I$mq$, $mq$size$mq$, $mq${"seed":71,"shape":"up","questions":[{"q":"$5,000 account, 1% risk, 20-pip stop on EURUSD ($10/pip/lot). Lot size?","options":["0.10","0.25","0.50"],"answer":1,"why":"$50 ÷ (20 × $10) = 0.25 lots."},{"q":"Same account, 1% risk, 50-pip stop. Lot size?","options":["0.10","0.25","1.00"],"answer":0,"why":"$50 ÷ (50 × $10) = 0.10 lots."},{"q":"Your stop gets wider. Your lot size should:","options":["Get bigger","Get smaller","Stay the same"],"answer":1,"why":"Wider stop → smaller lots, same dollar risk."}]}$mq$::jsonb),
($mq$drill-size-2$mq$, 4, $mq$Position Size II (Gold)$mq$, $mq$size$mq$, $mq${"seed":79,"shape":"range","questions":[{"q":"$5,000, 0.5% risk, gold stop $5 away ($10 per $0.10 per lot). Lot size?","options":["0.05","0.10","0.50"],"answer":0,"why":"$25 ÷ (50 × $10) = 0.05 lots."},{"q":"Why round lots DOWN, not up?","options":["Brokers require it","So you never risk more than planned","It increases RR"],"answer":1,"why":"Rounding down keeps risk at or below your limit."}]}$mq$::jsonb),
($mq$drill-mind-1$mq$, 5, $mq$Monster Spotting$mq$, $mq$mind$mq$, $mq${"seed":83,"shape":"up","questions":[{"q":"You lost a trade 5 minutes ago and want to re-enter bigger. Which monster?","options":["FOMO Wraith","Revenge Goblin","Hope Ghost"],"answer":1,"why":"Re-entering quickly after a loss is the Revenge Goblin."},{"q":"You moved your stop further away to \"give it room\". Which monster?","options":["Stop-Loss Thief","Boredom Bat","Early Exit Imp"],"answer":0,"why":"Moving the stop away is the Stop-Loss Thief."},{"q":"Nothing is happening, so you take a so-so setup. Which monster?","options":["News Banshee","Boredom Bat","Trend Defier"],"answer":1,"why":"Trading out of boredom is the Boredom Bat."}]}$mq$::jsonb)
on conflict (id) do update set zone = excluded.zone, title = excluded.title, kind = excluded.kind, payload = excluded.payload;
